// Shiki without inline styles: the CSP has style-src 'self' (no 'unsafe-inline'), so the browser
// drops every style="" attribute. With two themes and defaultColor: false, Shiki writes each token's
// colors as CSS variables (--shiki-light:#24292E;--shiki-dark:#E1E4E8); this transformer turns them
// into classes (cl-24292e cd-e1e4e8) and removes every style. The colors live in
// src/styles/code-theme.css (generated by scripts/code-theme.ts), and scripts/check-dist.ts fails the
// build if any style="" is left or a color class has no rule.

interface HastElement {
  type: "element";
  tagName: string;
  properties: Record<string, unknown>;
  children: HastNode[];
}
interface HastParent {
  type: string;
  children?: HastNode[];
}
type HastNode = HastElement | HastParent;

/** Classes for each declaration Shiki writes; what isn't listed is dropped (the CSS handles it). */
function classesOf(style: string): string[] {
  const classes: string[] = [];
  for (const declaration of style.split(";")) {
    const [rawName, ...rest] = declaration.split(":");
    const name = rawName?.trim().toLowerCase() ?? "";
    const value = rest.join(":").trim().toLowerCase();
    const theme = /^--shiki-(light|dark)(?:-(font-style|font-weight|text-decoration))?$/.exec(name);
    if (theme !== null) {
      const prefix = theme[1] === "light" ? "cl" : "cd";
      const property = theme[2];
      if (property === undefined) {
        const hex = /^#([0-9a-f]{3,8})$/.exec(value)?.[1];
        if (hex !== undefined) classes.push(`${prefix}-${hex}`);
      } else if (property === "font-style" && value === "italic") {
        classes.push(`${prefix}-italic`);
      } else if (property === "font-weight" && value === "bold") {
        classes.push(`${prefix}-bold`);
      } else if (property === "text-decoration" && value.includes("underline")) {
        classes.push(`${prefix}-underline`);
      }
    } else if (name === "user-select" && value === "none") {
      // The +/- of diff blocks.
      classes.push("code-no-select");
    } else if (name === "white-space" && value === "pre-wrap") {
      classes.push("code-wrap");
    }
    // --shiki-*-bg and overflow-x: the background and the scroll come from .astro-code.
  }
  return classes;
}

function convert(node: HastNode): void {
  if (node.type === "element" && "properties" in node) {
    const style = node.properties.style;
    if (typeof style === "string") {
      const extra = classesOf(style);
      if (extra.length > 0) {
        const current = node.properties.class;
        const existing = Array.isArray(current)
          ? current.map(String)
          : typeof current === "string"
            ? current.split(/\s+/).filter(Boolean)
            : [];
        node.properties.class = [...existing, ...extra].join(" ");
      }
    }
    delete node.properties.style;
  }
  for (const child of node.children ?? []) convert(child);
}

/** Shiki transformer: runs on the finished tree, after Astro's own (which adds overflow-x). */
export const shikiStyleToClass = {
  name: "spiderfolio:style-to-class",
  root(root: HastParent): void {
    convert(root);
  },
};
